            },
            "required": ["status", "summary", "steps", "failing_step", "evidence", "cause", "cause_source", "cause_quote", "suggested_fix", "packages", "confidence"],
            "additionalProperties": False,
        },
    },
]


@dataclass
class Action:
    """One thing the worker did in the sandbox."""

    kind: str  # run | background | write_file | wait_for_port | read_file | fetch
    input: dict[str, Any]
    step: int | None = None
    purpose: str | None = None
    ok: bool = True
    exit_code: int | None = None
    timed_out: bool = False
    output_tail: str = ""
    duration_s: float = 0.0

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @property
    def replayable(self) -> bool:
        return self.kind in ("run", "background", "write_file", "wait_for_port") and self.purpose in ("follow", "retry")


def http_fetch(url: str) -> str:
    """GET a URL; HTML becomes markdown. Raises on HTTP errors."""
    from markdownify import markdownify

    with httpx.Client(follow_redirects=True, timeout=30, headers={"User-Agent": "newt-docs/0.1"}) as client:
        response = client.get(url)
        response.raise_for_status()
    text = response.text
    if "html" in response.headers.get("content-type", ""):
        text = markdownify(text, heading_style="ATX")
        text = re.sub(r"\n{3,}", "\n\n", text)
    return text


@dataclass
class ToolBox:
    sandbox: Sandbox
    fetcher: Callable[[str], str] = http_fetch
    actions: list[Action] = field(default_factory=list)
    fetched: dict[str, str] = field(default_factory=dict)  # url -> full text, for the gate
    _failures: dict[int, int] = field(default_factory=dict)

    def handle(self, name: str, tool_input: dict[str, Any]) -> tuple[str, bool]:
        """Run one tool call. Returns (text for the model, is_error)."""
        handler = getattr(self, f"_tool_{name}", None)
        if handler is None or name == "report":
            return f"Unknown tool: {name}", True
        try:
            return handler(**tool_input), False
        except TypeError as e:
            return f"Bad arguments for {name}: {e}", True
        except (SandboxError, FileNotFoundError, IsADirectoryError, httpx.HTTPError) as e:
            return f"{type(e).__name__}: {e}", True

    # -- handlers ----------------------------------------------------------

    @tracing.span(kind="TOOL", name="sandbox.run")
    def _tool_run(self, command: str, step: int, purpose: str, timeout: int = 120, background: bool = False) -> str:
        if background:
            return self._background(command, step, purpose)
        timeout = max(1, min(int(timeout), 900))
        result = self.sandbox.exec(command, timeout=timeout)
        action = Action(
            "run", {"command": command, "timeout": timeout}, step, purpose,
            ok=result.ok, exit_code=result.exit_code, timed_out=result.timed_out,
            output_tail=result.output[-OUTPUT_TAIL_CHARS:], duration_s=round(result.duration_s, 2),
        )
        self.actions.append(action)
        status = "TIMED OUT" if result.timed_out else f"exit code {result.exit_code}"
        text = f"[{status}, {result.duration_s:.1f}s]\n{_tail(result.output)}"
        return text + self._failure_note(action)

    def _background(self, command: str, step: int, purpose: str) -> str:
        started = time.monotonic()
        proc = self.sandbox.start_background(command)
        time.sleep(1.5)  # let an instant crash show up
        alive = self.sandbox.background_alive(proc.name)
        logs = self.sandbox.background_logs(proc.name, tail_chars=OUTPUT_TAIL_CHARS)
        action = Action(
            "background", {"command": command}, step, purpose, ok=alive,
            exit_code=None if alive else 1, output_tail=logs, duration_s=round(time.monotonic() - started, 2),
        )
        self.actions.append(action)
        state = "running" if alive else "EXITED"
        text = f"[background process {proc.name} (pid {proc.pid}) {state}; log {proc.log_path}]\n{_tail(logs) or '(no output yet)'}"
        return text + self._failure_note(action)

    @tracing.span(kind="TOOL", name="sandbox.write_file")
    def _tool_write_file(self, path: str, content: str, step: int, purpose: str) -> str:
        abspath = self.sandbox.write_file(path, content)
        self.actions.append(Action("write_file", {"path": path, "content": content}, step, purpose))
        return f"Wrote {len(content)} chars to {abspath}"

    @tracing.span(kind="TOOL", name="sandbox.read_file")
    def _tool_read_file(self, path: str) -> str:
        content = self.sandbox.read_file(path)
        self.actions.append(Action("read_file", {"path": path}, output_tail=content[-OUTPUT_TAIL_CHARS:]))
        return _tail(content, 20_000)

    @tracing.span(kind="TOOL", name="sandbox.wait_for_port")
    def _tool_wait_for_port(self, port: int, step: int, purpose: str, timeout: int = 30) -> str:
        timeout = max(1, min(int(timeout), 300))
        started = time.monotonic()
        up = self.sandbox.wait_for_port(int(port), timeout=timeout)
        action = Action(
            "wait_for_port", {"port": int(port), "timeout": timeout}, step, purpose,
            ok=up, exit_code=0 if up else 1, duration_s=round(time.monotonic() - started, 2),
        )
        self.actions.append(action)
        text = f"Port {port} is accepting connections." if up else f"Nothing is listening on port {port} after {timeout}s."
        if not up:
            for name in self.sandbox.background:
                alive = "running" if self.sandbox.background_alive(name) else "EXITED"
                text += f"\n[background {name}: {alive}]\n{_tail(self.sandbox.background_logs(name), 3_000)}"
        return text + self._failure_note(action)

    @tracing.span(kind="TOOL", name="fetch")
    def _tool_fetch(self, url: str) -> str:
        started = time.monotonic()
        try:
            text = self.fetcher(url)
        except httpx.HTTPError as e:
            self.actions.append(Action("fetch", {"url": url}, ok=False, output_tail=str(e), duration_s=round(time.monotonic() - started, 2)))
            raise
        self.fetched[url] = text
        self.actions.append(Action("fetch", {"url": url}, output_tail=text[:500], duration_s=round(time.monotonic() - started, 2)))
        if len(text) > FETCH_MAX_CHARS:
            return text[:FETCH_MAX_CHARS] + f"\n[... {len(text) - FETCH_MAX_CHARS} more chars not shown ...]"
        return text

    # -- helpers -----------------------------------------------------------

    def _failure_note(self, action: Action) -> str:
        if action.ok or action.purpose == "diagnose" or action.step is None:
            return ""
        count = self._failures.get(action.step, 0) + 1
        self._failures[action.step] = count
        if count >= MAX_FAILURES_PER_STEP:
            return (
                f"\n\n[newt] Step {action.step} has failed {count} times. Stop retrying it: "
                "decide whose fault this is (agent / docs / human / glitch / unsure) and report or move on."
            )
        return ""


def _tail(text: str, limit: int = OUTPUT_TAIL_CHARS) -> str:
    if len(text) <= limit:
        return text
    return f"[... {len(text) - limit} earlier chars cut ...]\n" + text[-limit:]


def parse_tool_input(raw: Any) -> dict[str, Any]:
    if isinstance(raw, dict):
        return raw
    return json.loads(raw)
"""Worker loop + docs-fault gate, with a scripted fake model and real Docker sandboxes."""

from types import SimpleNamespace

import pytest

from newt.sandbox import docker_available
from newt.worker import Verdict, Worker, _explained, _signature

docker_only = pytest.mark.skipif(not docker_available(), reason="Docker daemon not available")

PAGE = """# Quickstart
1. Create `hello.py` containing `import json; print(json.dumps({"ok": True}))`
2. Run `python hello.py`
"""


class FakeClient:
    """Plays back scripted model turns. Each turn is a list of (tool name, input)."""

    def __init__(self, turns):
        self.turns = list(turns)
        self.calls = []
        self.beta = SimpleNamespace(messages=SimpleNamespace(create=self._create))

    def _create(self, **kwargs):
        self.calls.append({**kwargs, "messages": list(kwargs["messages"])})  # snapshot: the list keeps growing
        blocks = []
        if self.turns:
            for i, (name, tool_input) in enumerate(self.turns.pop(0)):
                blocks.append(SimpleNamespace(type="tool_use", id=f"t{len(self.calls)}_{i}", name=name, input=tool_input))
        else:
            blocks.append(SimpleNamespace(type="text", text="done"))
        return SimpleNamespace(
            content=blocks,
            stop_reason="tool_use" if blocks[0].type == "tool_use" else "end_turn",
            usage=SimpleNamespace(input_tokens=100, output_tokens=20, cache_read_input_tokens=0, cache_creation_input_tokens=0),
        )


def report(status, **extra):
    base = dict(status=status, summary="s", steps=[], failing_step=None, evidence=None, cause="",
                cause_source="", cause_quote="", suggested_fix="", packages=[], confidence=0.9)
    base.update(extra)
    return ("report", base)


BROKEN_STEP = "python -c 'import json; json.dumps2({})'"
CHANGELOG_URL = "https://example.test/changelog"
CHANGELOG = "## 2.0\n- `json.dumps2` was removed; use `json.dumps` instead.\n"


def broken_run(quote="`json.dumps2` was removed", fetch=True):
    turns = [
        [("run", {"command": "mkdir -p proj && cd proj", "step": 1, "purpose": "follow"})],
        [("run", {"command": BROKEN_STEP, "step": 2, "purpose": "follow"})],
    ]
    if fetch:
        turns.append([("fetch", {"url": CHANGELOG_URL})])
    turns.append([report(
        "docs_broken",
        failing_step={"index": 2, "text": "Run the dumps2 example"},
        evidence={"command": BROKEN_STEP, "output_tail": "AttributeError"},
        cause="dumps2 was removed in 2.0", cause_source=CHANGELOG_URL if fetch else "",
        cause_quote=quote if fetch else "", suggested_fix="Use json.dumps",
    )])
    return turns


def make_worker(turns, **kw):
    return Worker(PAGE, "quickstart.md", client=FakeClient(turns), fetcher=lambda url: CHANGELOG, **kw)


@docker_only
def test_pass_run_records_actions_and_uses_one_sandbox():
    turns = [
        [("write_file", {"path": "hello.py", "content": 'import json; print(json.dumps({"ok": True}))\n', "step": 1, "purpose": "follow"})],
        [("run", {"command": "python hello.py", "step": 2, "purpose": "follow"})],
        [report("pass")],
    ]
    w = make_worker(turns)
    result = w.run()
    assert result.verdict.status == "pass"
    assert result.gate.action == "none"
    assert [a.kind for a in result.actions] == ["write_file", "run"]
    assert '{"ok": true}' in result.actions[1].output_tail
    assert result.turns == 3
    # The tool result for the run went back to the model with the output.
    last_user = w.client.calls[-1]["messages"][-1]
    assert '{"ok": true}' in last_user["content"][0]["content"]


@docker_only
def test_docs_broken_with_repro_and_quote_passes_gate():
    result = make_worker(broken_run()).run()
    assert result.verdict.status == "docs_broken"
    assert result.gate.reproduced and result.gate.explained
    assert result.gate.action == "write_fix"
    assert result.gate.fixed is None
    assert "attributeerror" in _signature(result.gate.repro_output_tail)


@docker_only
def test_docs_broken_without_evidence_is_demoted_to_unsure():
    result = make_worker(broken_run(fetch=False)).run()
    assert result.verdict.status == "unsure"
    assert result.verdict.model_status == "docs_broken"
    assert result.gate.action == "flag"
    assert result.gate.reproduced is True
    assert result.gate.explained is False


@docker_only
def test_made_up_quote_is_not_explained():
    result = make_worker(broken_run(quote="dumps2 was renamed to dump_string")).run()
    assert result.verdict.status == "unsure"
    assert result.gate.explained is False


@docker_only
def test_failure_that_does_not_reproduce_is_unsure():
    # The agent's own diagnosis command broke the sandbox; the page itself is fine.
    # The replay skips diagnose actions, so in a fresh sandbox the step passes.
    step = "if [ -e /tmp/broken-by-agent ]; then echo 'OSError: busy'; exit 1; fi; echo ok"
    turns = [
        [("run", {"command": "touch /tmp/broken-by-agent", "step": 1, "purpose": "diagnose"})],
        [("run", {"command": step, "step": 1, "purpose": "follow"})],
        [("fetch", {"url": CHANGELOG_URL})],
        [report("docs_broken", failing_step={"index": 1, "text": "step"}, evidence={"command": step, "output_tail": "OSError"},
                cause="c", cause_source=CHANGELOG_URL, cause_quote="`json.dumps2` was removed", suggested_fix="f")],
    ]
    result = make_worker(turns).run()
    assert result.gate.reproduced is False
    assert result.verdict.status == "unsure"


@docker_only
def test_gate_off_sends_everything():
    result = make_worker(broken_run(fetch=False), gate=False).run()
    assert result.verdict.status == "docs_broken"
    assert result.gate.action == "send_fix"


@docker_only
def test_budget_gives_up_instead_of_faking_a_pass():
    turns = [[("run", {"command": "true", "step": 1, "purpose": "follow"})]] * 10
    result = make_worker(turns, max_turns=3).run()
    assert result.verdict.status == "agent_gave_up"
    assert result.turns == 3


@docker_only
def test_invalid_report_is_returned_to_model_and_retried():
    turns = [[("report", {"status": "great"})], [report("pass")]]
    w = make_worker(turns)
    result = w.run()
    assert result.verdict.status == "pass"
    err = w.client.calls[1]["messages"][-1]["content"][0]
    assert err["is_error"] and "Invalid report" in err["content"]


@docker_only
def test_model_that_stops_without_report_gives_up():
    result = make_worker([]).run()
    assert result.verdict.status == "agent_gave_up"
    assert result.turns == 2  # one nudge, then give up


@docker_only
def test_repeated_failures_trigger_decide_note():
    turns = [[("run", {"command": "false", "step": 1, "purpose": "retry"})]] * 3 + [[report("unsure")]]
    w = make_worker(turns)
    w.run()
    third_result = w.client.calls[3]["messages"][-1]["content"][0]["content"]
    assert "has failed 3 times" in third_result


def test_request_shape_for_sonnet_5_5():
    calls = []

    class Stop(Exception):
        pass

    def create(**kw):
        calls.append(kw)
        raise Stop

    client = SimpleNamespace(beta=SimpleNamespace(messages=SimpleNamespace(create=create)))
    w = Worker(PAGE, client=client, sandbox_factory=lambda: SimpleNamespace(start=lambda: None, teardown=lambda: None))
    with pytest.raises(Stop):
        w.run()
    kw = calls[0]
    assert kw["model"] == "claude-sonnet-5-5"
    assert "tool_choice" not in kw and "temperature" not in kw  # both rejected on this model
    assert kw["fallbacks"] == "default" and kw["betas"] == ["server-side-fallback-2026-07-01"]
    assert {t["name"] for t in kw["tools"]} == {"run", "write_file", "read_file", "wait_for_port", "fetch", "report"}


def test_explained_requires_fetched_source_and_real_quote():
    v = Verdict("docs_broken", cause_source="https://x.test/c/", cause_quote="charge()  was renamed")
    assert _explained(v, {"https://x.test/c": "In 2.0, charge() was renamed to payments.create()."})[0]
    assert not _explained(v, {})[0]
    assert not _explained(v, {"https://x.test/c": "nothing relevant"})[0]


def test_signature_picks_last_error_line():
    out = "Traceback (most recent call last):\n  File \"x\"\nAttributeError: module 'lumen' has no attribute 'charge'\n"
    assert _signature(out) == "attributeerror: module 'lumen' has no attribute 'charge'"
import os

import pytest

from newt import tracing


def test_parse_env_handles_quotes_comments_and_export():
    text = """
# comment
export A=1
B = "two words"
C='x=y'
D=plain # trailing comment
EMPTY=
"""
    assert tracing._parse_env(text) == {"A": "1", "B": "two words", "C": "x=y", "D": "plain"}


def test_load_env_does_not_override_existing(tmp_path, monkeypatch):
    env = tmp_path / ".env"
    env.write_text("NEWT_TEST_KEY=from_file\nNEWT_TEST_OTHER=other\n")
    monkeypatch.setenv("NEWT_TEST_KEY", "from_env")
    monkeypatch.delenv("NEWT_TEST_OTHER", raising=False)
    tracing.load_env(env)
    assert os.environ["NEWT_TEST_KEY"] == "from_env"
    assert os.environ["NEWT_TEST_OTHER"] == "other"
    monkeypatch.delenv("NEWT_TEST_OTHER")


def test_anthropic_client_requires_key(monkeypatch, tmp_path):
    monkeypatch.delenv("ANTHROPIC_API_KEY", raising=False)
    monkeypatch.setattr(tracing, "load_env", lambda *a, **k: {})
    with pytest.raises(RuntimeError, match="ANTHROPIC_API_KEY"):
        tracing.anthropic_client()
